-- ============================================================================
-- Azshara Crater - Quest Text Lore Pass (classic-WoW voice + title cleanup)
-- Date: 2026-07-14
-- Rewrites LogTitle/descriptions/objective/turn-in/completion text for all
-- Azshara Crater quests into lore-accurate classic-WoW voice. Objectives,
-- counts, creature/item names and quest IDs are unchanged.
-- Welcome-quest dedup: 300100 retitled (no longer 'Welcome'); 820056 is the
-- single canonical 'Welcome to Azshara Crater' (spelling fixed); 820057 kept
-- as the distinct 'Welcome to Dark Chaos' realm intro.
-- ============================================================================

UPDATE `quest_template` SET `LogTitle` = 'Take Up the Watch', `LogDescription` = 'Ready yourself for duty with Scout Thalindra at the outpost.', `QuestDescription` = 'Stay your step, $N, and keep your voice low. This crater is no meadow to wander. When the Well of Eternity broke the world, it left this bowl drowning in wild magic, and that magic pulls all manner of hungering things down into it.$B$BStill, we hold. A handful of Sentinels, one stubborn dwarf, and now you. Take this supply bag and ready yourself. If you mean to earn a place at this outpost, I will find work enough for a $C of your mettle.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You stand ready for duty.' WHERE `ID` = 300100;
UPDATE `quest_offer_reward` SET `RewardText` = 'Good. Elune knows we need every willing hand. This crater teems with things that would see our tents burned by morning. Keep your blade close, $N, and your eyes closer.' WHERE `ID` = 300100;
UPDATE `quest_request_items` SET `CompletionText` = 'Have you spoken to Scout Thalindra yet?' WHERE `ID` = 300100;
UPDATE `quest_template` SET `LogTitle` = 'Fang and Tusk', `LogDescription` = 'Slay 6 Young Thistle Boars and 6 Mangy Wolves.', `QuestDescription` = 'Ye want to be useful, $N? Then start with the beasts. The boars have gone mean and the wolves bolder still, all of ''em stirred wrong by whatever sours the air down here.$B$BGo thin ''em out. Six o'' the young thistle boars and six o'' the mangy wolves ought to give the camp room to breathe. A hunter earns respect one clean kill at a time.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The boars and wolves have been thinned.' WHERE `ID` = 300101;
UPDATE `quest_offer_reward` SET `RewardText` = 'Aye, that''s the way of it. The camp''s a sight safer with those beasts culled. Good huntin'', $N.' WHERE `ID` = 300101;
UPDATE `quest_request_items` SET `CompletionText` = 'Those beasts still prowl the camp''s edge. Have ye thinned their numbers?' WHERE `ID` = 300101;
UPDATE `quest_template` SET `LogTitle` = 'Bears at the Larder', `LogDescription` = 'Slay 8 Young Forest Bears.', `QuestDescription` = 'Bears, $N. Great shaggy thieves, the lot of ''em. They''ve caught the scent of our stores, and now they''ll not leave off till the larder''s bare.$B$BPut down eight o'' the young forest bears prowlin'' near the outpost. Do it clean, and there''s silver waitin'' for ye.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The forest bears have been driven off.' WHERE `ID` = 300102;
UPDATE `quest_offer_reward` SET `RewardText` = 'Hah! That''ll learn ''em to raid a dwarf''s larder. Here now, take yer pay, $N. Ye earned every bit of it.' WHERE `ID` = 300102;
UPDATE `quest_request_items` SET `CompletionText` = 'I still spy bears sniffin'' round the stores. See to ''em.' WHERE `ID` = 300102;
UPDATE `quest_template` SET `LogTitle` = 'Restless Timberlings', `LogDescription` = 'Slay 8 Timberlings.', `QuestDescription` = 'Have you marked the little tree-things that walk the underbrush, $N? Timberlings, we name them, saplings given a crude and clumsy life. They should be harmless. They are not.$B$BSomething in the crater''s wild magic has set them stirring wrong. Fell eight of them, and I will study what quickens their sap. Knowledge is a Sentinel''s first weapon.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Timberlings have been felled.' WHERE `ID` = 300103;
UPDATE `quest_offer_reward` SET `RewardText` = 'Fascinating... the sap fairly crackles with unspent magic. This crater changes even the gentlest of growing things. I have much to consider.' WHERE `ID` = 300103;
UPDATE `quest_request_items` SET `CompletionText` = 'I still need the essence of those Timberlings. Have you felled them?' WHERE `ID` = 300103;
UPDATE `quest_template` SET `LogTitle` = 'The Webwood Ridge', `LogDescription` = 'Slay 10 Webwood Lurkers.', `QuestDescription` = 'The northern ridge crawls, $N. Webwood lurkers have spun their nests thick across the rocks, and each day they creep a little nearer the outpost.$B$BI will not have my scouts wrapped in silk before they can cry a warning. Burn them out, ten of the lurkers and no fewer, and the ridge is ours again.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Webwood Lurkers have been cleared.' WHERE `ID` = 300104;
UPDATE `quest_offer_reward` SET `RewardText` = 'The ridge is quiet again. Well done, $N. One less dark path for the crater to send its horrors through.' WHERE `ID` = 300104;
UPDATE `quest_request_items` SET `CompletionText` = 'The lurkers still hold the ridge. Return when it is clear.' WHERE `ID` = 300104;
UPDATE `quest_template` SET `LogTitle` = 'What Stirs the Grove', `LogDescription` = 'Defeat 12 Timberlings.', `QuestDescription` = 'The Timberlings do not simply wander, $N. They gather, they turn, as though some old will bends them to a single purpose. I would know what wakes beneath this grove.$B$BStrike down twelve of them. Cut deep enough into their number, and whatever commands them may show itself. Be ready if it does.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have thinned the Timberlings'' ranks.' WHERE `ID` = 300105;
UPDATE `quest_offer_reward` SET `RewardText` = 'You faced them and returned whole? Then perhaps this crater has not yet swallowed our hopes after all. You have earned my trust, $N. It is not given lightly.' WHERE `ID` = 300105;
UPDATE `quest_request_items` SET `CompletionText` = 'The grove still stirs. Do not return until their ranks are broken.' WHERE `ID` = 300105;
UPDATE `quest_template` SET `LogTitle` = 'The Northern Pass', `LogDescription` = 'Travel to the northern checkpoint and survey the area.', `QuestDescription` = 'You have proven steady, $N, and I have need of steady eyes. If this outpost is ever to grow, we must know what waits along the northern pass before we set a single tent there.$B$BTravel to the northern checkpoint and mark what you find. Tracks, nests, anything that moves. Come back with more than guesses.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have surveyed the northern pass.' WHERE `ID` = 300106;
UPDATE `quest_offer_reward` SET `RewardText` = 'The pass is clear enough to hold? Good. Then we push north. You have won this outpost its next foothold, $N.' WHERE `ID` = 300106;
UPDATE `quest_request_items` SET `CompletionText` = 'Have you reached the northern checkpoint?' WHERE `ID` = 300106;
UPDATE `quest_template` SET `LogTitle` = 'Hides Against the Cold', `LogDescription` = 'Collect 8 Light Hides.', `QuestDescription` = 'Nights bite hard down in this bowl, $N, and half the camp''s beddin'' is little more than rags. Won''t do. Cold soldiers make slow ones, and slow ones make dead ones.$B$BThe wolves hereabouts carry good hide. Bring me eight light hides off ''em, and we''ll have folk sleepin'' warm before the frost sets in.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have gathered 8 Light Hides.' WHERE `ID` = 300107;
UPDATE `quest_offer_reward` SET `RewardText` = 'Aye, that''s fine hide, thick and warm. The camp''ll thank ye come nightfall, and so do I. Well done, $N.' WHERE `ID` = 300107;
UPDATE `quest_request_items` SET `CompletionText` = 'Still short on hides. Winter won''t wait for ye, $N.' WHERE `ID` = 300107;
UPDATE `quest_template` SET `LogTitle` = 'Tide of Murlocs', `LogDescription` = 'Slay 10 Murloc Foragers along the coast.', `QuestDescription` = 'The Sundering reshaped even this shore, $N, and the murlocs were quick to claim it. Now their foragers slink up along our supply lines and haul off whatever they can carry.$B$BDrive ten of the murloc foragers back into the surf. Let them learn this crater is not theirs to pick clean.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have slain the Murloc Foragers.' WHERE `ID` = 300108;
UPDATE `quest_template` SET `LogTitle` = 'The Restless Dead', `LogDescription` = 'Destroy 10 Dreadbone Skeletons.', `QuestDescription` = 'You feel it, do you not? The air here will not rest. These ruins were part of Zin-Azshari once, and the dead of that drowned court do not lie quiet.$B$BDreadbone skeletons claw up from the rubble faster than I can catalogue them. Put ten of them back down, $N. The living have work to do in these stones, and the dead keep interrupting it.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Dreadbone Skeletons have been laid to rest.' WHERE `ID` = 300200;
UPDATE `quest_offer_reward` SET `RewardText` = 'Quieted, for now. They will rise again, they always do, but you have bought us the time we needed. You have my thanks, $N.' WHERE `ID` = 300200;
UPDATE `quest_request_items` SET `CompletionText` = 'The dead still rattle among the stones. Have you put them down?' WHERE `ID` = 300200;
UPDATE `quest_template` SET `LogTitle` = 'Rifts in the Ley', `LogDescription` = 'Destroy 8 Lesser Voidwalkers.', `QuestDescription` = 'There is a wrongness threading these ruins, $N. Not the wild arcane the crater leaks, but something colder. Void. It seeps in wherever the ley lines have frayed, and things crawl through the seams.$B$BLesser voidwalkers are gathering at the broken lines. Destroy eight of them before the rift they widen becomes a wound we cannot close.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Lesser Voidwalkers have been destroyed.' WHERE `ID` = 300201;
UPDATE `quest_offer_reward` SET `RewardText` = 'Void energies, unmistakable. I will see these traces sealed away where they can do no more harm. You have a careful hand, $N. I may have further need of it.' WHERE `ID` = 300201;
UPDATE `quest_request_items` SET `CompletionText` = 'The voidwalkers still bleed through the ley lines. We need them gone.' WHERE `ID` = 300201;
UPDATE `quest_template` SET `LogTitle` = 'Golems Run Wild', `LogDescription` = 'Destroy 8 Harvest Golems.', `QuestDescription` = 'Some expedition before ours left these harvest golems to tend the ruins, and the crater''s magic has since driven them mad. Now they shatter the very things they were built to protect.$B$BDismantle eight of them, $N. Whatever survives their rampage we can still salvage, and I would far rather the salvage came from them than from us.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Harvest Golems have been dismantled.' WHERE `ID` = 300202;
UPDATE `quest_offer_reward` SET `RewardText` = 'Good. Their cores are still sound, more than enough to serve constructs of our own. Waste nothing in a place like this, $N. That is the first rule of ruins.' WHERE `ID` = 300202;
UPDATE `quest_request_items` SET `CompletionText` = 'The golems still rampage. Dismantle them before they wreck what remains.' WHERE `ID` = 300202;
UPDATE `quest_template` SET `LogTitle` = 'A Voice Among the Ruins', `LogDescription` = 'Speak with the Spirit of Kelvenar in the ruins.', `QuestDescription` = 'A ghost walks the far ruins, $N. I have watched him from a safe distance. He does not rage as the others do. He grieves. There is old memory in that spirit, and memory is the one thing these stones refuse to give me.$B$BGo to him. Speak gently. If he remembers what this place once was, I would hear it from one who lived it.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have spoken with the Spirit of Kelvenar.' WHERE `ID` = 300203;
UPDATE `quest_offer_reward` SET `RewardText` = 'He spoke to you? Then there is more sorrow buried here than even I had feared. The Highborne brought this ruin upon themselves, yet that makes the mourning no lighter. Thank you, $N.' WHERE `ID` = 300203;
UPDATE `quest_request_items` SET `CompletionText` = 'The spirit lingers still, waiting. Go to him. He means you no harm.' WHERE `ID` = 300203;
UPDATE `quest_template` SET `LogTitle` = 'The Wailing Noble', `LogDescription` = 'Defeat 12 Skeletal Warriors.', `QuestDescription` = 'You wear your living breath so lightly, mortal. Once, so did I.$B$BBehold what remains of Her Majesty''s guard: the Skeletal Warriors who stood the walls of Zin-Azshari, and stand them yet, though the walls are drowned and the Queen long since fled to the deep. They know no rest, only the old command. Twelve of them bar the way, $N. Break their ranks, and grant them the ending I cannot give myself.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have broken the guard of the Wailing Noble.' WHERE `ID` = 300204;
UPDATE `quest_offer_reward` SET `RewardText` = 'It is done. The Wailing Noble is silent, his torment ended at last. You have given the dead what the living never could: mercy. Go in peace, $N. Few in this crater ever will.' WHERE `ID` = 300204;
UPDATE `quest_request_items` SET `CompletionText` = 'The Noble''s guard still keeps its endless watch. They will not rest until you make it so.' WHERE `ID` = 300204;
UPDATE `quest_template` SET `LogTitle` = 'Varo''then''s Journal', `LogDescription` = 'Retrieve Varo''then''s Journal from the ruins by slaying 15 Skeletons.', `QuestDescription` = 'Among the bones of this court lies a journal, $N. The writings of one Captain Varo''then, Azshara''s own champion in the days before the Sundering. If any hand set down what the Highborne dared here, it was his.$B$BThe restless dead guard it still, whether they know it or not. Cut through fifteen of the skeletons and bring me that journal. I must learn how deep their folly truly ran.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have recovered Varo''then''s Journal.' WHERE `ID` = 300205;
UPDATE `quest_offer_reward` SET `RewardText` = 'This... this confirms every fear I carried into these ruins. The Highborne did not merely wield the arcane. They gorged upon it, until it remade them body and soul. We stand in the ashes of their hunger, $N. Let us be the wiser for it.' WHERE `ID` = 300205;
UPDATE `quest_request_items` SET `CompletionText` = 'The journal is still out there, somewhere among the bones. Keep searching.' WHERE `ID` = 300205;
UPDATE `quest_template` SET `LogTitle` = 'To the Eastern Slopes', `LogDescription` = 'Travel to the eastern slopes and find the Orc Scout.', `QuestDescription` = 'The interference thickens toward the eastern slopes, $N. My instruments go blind the moment I turn them that way. I will not send you in wholly alone.$B$BAn orc scout works those slopes for the Horde expedition. Strange bedfellows, I know, but in this crater the living must lean on the living. Find him, and see what he has learned.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found the Orc Scout.' WHERE `ID` = 300206;
UPDATE `quest_offer_reward` SET `RewardText` = 'You found him, and both of you in one piece. Good. The slopes are his charge now, and yours besides, if you will take them. Watch yourself out there, $N.' WHERE `ID` = 300206;
UPDATE `quest_request_items` SET `CompletionText` = 'The eastern slopes are treacherous. Have you found the orc scout?' WHERE `ID` = 300206;
UPDATE `quest_template` SET `LogTitle` = 'Dust of the Fallen', `LogDescription` = 'Collect 10 Gold Dust.', `QuestDescription` = 'When these skeletons fall, $N, they crumble to a fine gold dust. The arcane that saturated the Highborne in life, still clinging to them in death. It is a rare reagent, and I will not see it blow away on the wind.$B$BGather ten measures of the gold dust for me. What destroyed them may yet serve the living.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have gathered 10 Gold Dust.' WHERE `ID` = 300207;
UPDATE `quest_offer_reward` SET `RewardText` = 'Ah, feel how it hums against the skin. Potent, and pure. There is a bitter irony in it, that the Highborne''s ruin should become our reagent. Still, we waste nothing here. My thanks, $N.' WHERE `ID` = 300207;
UPDATE `quest_request_items` SET `CompletionText` = 'I have not gathered enough dust for my work. Return when you have more.' WHERE `ID` = 300207;
UPDATE `quest_template` SET `LogTitle` = 'Poisoned Waters', `LogDescription` = 'Destroy 8 Fouled Water Spirits.', `QuestDescription` = 'The waters that pool through these ruins were once pure ley-fed springs, $N. No longer. Something has fouled them to their depths, and the spirits born of that water have turned poisonous along with it.$B$BEight of the fouled water spirits drift near the fractured lines. Destroy them before their corruption spreads deeper into the ley and beyond our reach.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have destroyed the Fouled Water Spirits.' WHERE `ID` = 300208;
UPDATE `quest_template` SET `LogTitle` = 'A Test of Steel', `LogDescription` = 'Slay 10 Haldarr Satyrs (or any satyr) in the woods east of the outpost.', `QuestDescription` = 'You come to my fire wanting to fight? Good. Talk is wind.$B$BThe Haldarr satyrs den in the woods east of here, fel-twisted things that were night elves once and remember none of it. They reek of the same broken magic that scarred this crater.$B$BGo east, $C. Cut down ten of them and come back bloodied. Then I will know your steel is worth my time.', `QuestCompletionLog` = 'Ten satyrs slain.' WHERE `ID` = 300300;
UPDATE `quest_offer_reward` SET `RewardText` = 'Hah. Ten of them dead, and you still stand.$B$BThe Haldarr will feel that loss. You have the steel I hoped for, $N.' WHERE `ID` = 300300;
UPDATE `quest_request_items` SET `CompletionText` = 'The satyrs still prowl the eastern wood. Go back and finish the work.' WHERE `ID` = 300300;
UPDATE `quest_template` SET `LogTitle` = 'Ten Cursed Horns', `LogDescription` = 'Collect 10 Satyr Horns.', `QuestDescription` = 'The satyrs grow their horns thick with the crater''s corruption, $N. Ground to powder, that filth burns clean in fire and wards our blades against their poison.$B$BBring me ten Satyr Horns, and take them from fresh kills. Old horns crumble to dust in the hand and are worth nothing.', `QuestCompletionLog` = 'Ten Satyr Horns gathered.' WHERE `ID` = 300301;
UPDATE `quest_offer_reward` SET `RewardText` = 'Ten horns, all sound. Good.$B$BThe grinding is grim work, but this powder keeps their taint off our steel. My thanks, $N.' WHERE `ID` = 300301;
UPDATE `quest_request_items` SET `CompletionText` = 'You have not gathered enough horns yet. Return to the satyr dens.' WHERE `ID` = 300301;
UPDATE `quest_template` SET `LogTitle` = 'Silence the Totems', `LogDescription` = 'Destroy 5 Thistlefur Totems.', `QuestDescription` = 'The Thistlefur were furbolgs once, honest beasts of the wood. The crater''s madness took them, and now they raise totems that pulse with that same sick power.$B$BEvery totem left standing feeds their frenzy, $N. Go into their camp and smash five Thistlefur Totems to splinters. Rob them of the magic before we rob them of their heads.', `QuestCompletionLog` = 'Five Thistlefur Totems destroyed.' WHERE `ID` = 300302;
UPDATE `quest_offer_reward` SET `RewardText` = 'The totems are kindling now? Good.$B$BTheir dark magic sputters without them. The Thistlefur will break all the easier.' WHERE `ID` = 300302;
UPDATE `quest_request_items` SET `CompletionText` = 'The totems still stand. Cut down the totemics who guard them and smash the poles.' WHERE `ID` = 300302;
UPDATE `quest_template` SET `LogTitle` = 'The Captive Elder', `LogDescription` = 'Kill 10 Thistlefur Shamans.', `QuestDescription` = 'The Thistlefur hold an elder caged deep in their camp, and it is their shamans who keep the wards that bind him.$B$BI have no love for cages, $N, whatever beast sits inside one. Kill ten Thistlefur Shamans and their binding magic will fray. Then we can cut the elder loose and be done with it.', `QuestCompletionLog` = 'Ten Thistlefur Shamans defeated.' WHERE `ID` = 300303;
UPDATE `quest_offer_reward` SET `RewardText` = 'The shamans are dead and their wards unravel.$B$BThe elder will taste free air soon. You have my respect, $N.' WHERE `ID` = 300303;
UPDATE `quest_request_items` SET `CompletionText` = 'The shamans still chant and the wards still hold. Silence them.' WHERE `ID` = 300303;
UPDATE `quest_template` SET `LogTitle` = 'Rot at the Root', `LogDescription` = 'Kill 15 Thistlefur Avengers.', `QuestDescription` = 'The rot in these furbolgs runs deepest in their Avengers, $N. Hulking, armored brutes, the corruption''s chosen fists.$B$BStrike at the top and the rest lose their spine. Fifteen Thistlefur Avengers is hard work. I would not send a weakling to do it.', `QuestCompletionLog` = 'Fifteen Thistlefur Avengers slain.' WHERE `ID` = 300304;
UPDATE `quest_offer_reward` SET `RewardText` = 'Their strongest lie broken.$B$BWith the Avengers gone the corruption has nothing left to lean on. Well fought, $N.' WHERE `ID` = 300304;
UPDATE `quest_request_items` SET `CompletionText` = 'The Avengers still guard the camp''s heart. Cut them down.' WHERE `ID` = 300304;
UPDATE `quest_template` SET `LogTitle` = 'Drive Them from the Wood', `LogDescription` = 'Defeat 20 Thistlefurs of any kind.', `QuestDescription` = 'Now we finish it. No more picking at the edges. We drive the Thistlefur from these woods for good.$B$BWade into their camp and put down twenty of them, $N, whatever they are: shaman, avenger, whelp, it makes no difference. Break their numbers and break their nerve.$B$BGo. Make it loud.', `QuestCompletionLog` = 'Twenty Thistlefurs defeated.' WHERE `ID` = 300305;
UPDATE `quest_offer_reward` SET `RewardText` = 'Twenty down and the rest running!$B$BThe wood is ours again, $N. That was a fight worth singing about.' WHERE `ID` = 300305;
UPDATE `quest_request_items` SET `CompletionText` = 'The Thistlefur still hold their ground. The assault is not yet finished.' WHERE `ID` = 300305;
UPDATE `quest_template` SET `LogTitle` = 'Word for Thalindra', `LogDescription` = 'Return to Scout Thalindra.', `QuestDescription` = 'You have done this wood a great service, $N, and word of it belongs with the night elves who watch over the crater.$B$BReturn to Scout Thalindra at the outpost and tell her the Thistlefur are broken. She trusts my scouts little. A warrior of your kind speaking plainly will carry more weight than my word ever could.', `QuestCompletionLog` = 'Report to Scout Thalindra.' WHERE `ID` = 300306;
UPDATE `quest_offer_reward` SET `RewardText` = 'Broken and driven off, truly?$B$BThen Gor''nash and his scouts have earned their place at our fire this once. You have my thanks, $N. The eastern wood can breathe again.' WHERE `ID` = 300306;
UPDATE `quest_request_items` SET `CompletionText` = 'Have you carried word of our victory to Scout Thalindra?' WHERE `ID` = 300306;
UPDATE `quest_template` SET `LogTitle` = 'Beads of the Thistlefur', `LogDescription` = 'Collect 10 Gnoll War Beads.', `QuestDescription` = 'Strange thing, this. The Thistlefur string beads through their fur the way the gnolls do, the same crude craft. My scouts fear the corruption is creeping from beast to beast, and I mean to know.$B$BBring me ten Gnoll War Beads off their bodies, $N. If the taint jumps between tribes, better we learn it now than at the point of a spear.', `QuestCompletionLog` = 'Ten Gnoll War Beads gathered.' WHERE `ID` = 300307;
UPDATE `quest_offer_reward` SET `RewardText` = 'Ten beads, all of the same make.$B$BThis tells me more than I wanted to know. The rot does not care what wears it. My thanks, $N.' WHERE `ID` = 300307;
UPDATE `quest_request_items` SET `CompletionText` = 'You have not brought enough beads yet. Search the Thistlefur dead.' WHERE `ID` = 300307;
UPDATE `quest_template` SET `LogTitle` = 'Teeth in the Shallows', `LogDescription` = 'Hunt 6 Giant Wetlands Crocolisks.', `QuestDescription` = 'The crocolisks in the river have swollen fat and mean on the crater''s tainted water. Great brutes now, big as war-boars, and they have started dragging our pack-beasts under.$B$BOur supply road runs right past their bank, $N. Hunt down six Giant Wetlands Crocolisks before they take the whole caravan next.', `QuestCompletionLog` = 'Six Giant Wetlands Crocolisks hunted.' WHERE `ID` = 300308;
UPDATE `quest_template` SET `LogTitle` = 'Break the Spitelash', `LogDescription` = 'Kill 12 Spitelash Warriors.', `QuestDescription` = 'The tide brings the naga, $N, and the Spitelash are the worst of them. Cold-blooded killers who reckon this river theirs by ancient right.$B$BThey were Highborne once, drowned and remade, and the crater''s old magic called them crawling back to the light. I mean to send them down to the deep again.$B$BStrike the shore. Kill twelve Spitelash Warriors and remind the sea it does not command this ground.', `QuestCompletionLog` = 'Twelve Spitelash Warriors slain.' WHERE `ID` = 300400;
UPDATE `quest_offer_reward` SET `RewardText` = 'Twelve fewer serpents fouling my shore.$B$BThe river runs a little cleaner for it. The tide always pushes back, $N. So must we.' WHERE `ID` = 300400;
UPDATE `quest_template` SET `LogTitle` = 'Shells for the Wall', `LogDescription` = 'Kill 10 Makrura Shellhide.', `QuestDescription` = 'The Makrura scuttle these shallows in their thousands, and the Shellhide wear plate no blade of ours cracks easily.$B$BWaste, I call it. Those shells would armor our bunkers against the naga tide better than any timber we could haul in.$B$BGo to the water''s edge and slay ten Makrura Shellhide, $N. We will strip the shells from what you leave behind.', `QuestCompletionLog` = 'Ten Makrura Shellhide slain.' WHERE `ID` = 300401;
UPDATE `quest_offer_reward` SET `RewardText` = 'Ten shells, thick as a ship''s hull.$B$BThese will turn a spear where timber would splinter. The wall stands stronger for your work, $N.' WHERE `ID` = 300401;
UPDATE `quest_template` SET `LogTitle` = 'The Arcane Gluttons', `LogDescription` = 'Kill 8 Arcane Devourers.', `QuestDescription` = 'There is a hunger loose along the shore, $N. Arcane Devourers, spawned from the raw power bleeding out of this crater. They drink magic the way a whirlpool drinks a boat, and my mages cannot hold a spell within sight of them.$B$BEight of them prowl the tide line. Destroy them before they swallow every last spell we have left to fight the naga with.', `QuestCompletionLog` = 'Eight Arcane Devourers destroyed.' WHERE `ID` = 300402;
UPDATE `quest_offer_reward` SET `RewardText` = 'The devourers are undone, and there is magic in the air again.$B$BMy spellcasters can breathe. That hunger would have left us blind and weaponless. Well done, $N.' WHERE `ID` = 300402;
UPDATE `quest_template` SET `LogTitle` = 'Scales of the Blue', `LogDescription` = 'Kill 6 Blue Drakes.', `QuestDescription` = 'Look to the skies over the water and you will see them, $N. Blue Drakes, drawn like moths to the arcane fire burning in this crater.$B$BI''ll not pretend it is only duty. A blue drake''s scales fetch a fortune from the right buyer, and a Wavemaster''s war chest runs dry same as any other.$B$BBring down six of them and strip their scales. Storm and coin both favor the bold.', `QuestCompletionLog` = 'Six Blue Drakes slain.' WHERE `ID` = 300403;
UPDATE `quest_offer_reward` SET `RewardText` = 'Six sets of scales, each one shining like deep water.$B$BThese will fetch a fine price, enough to keep spears in my soldiers'' hands. My thanks, $N.' WHERE `ID` = 300403;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Prince Nazjak', `LogDescription` = 'Slay Prince Nazjak.', `QuestDescription` = 'Every serpent tide has its head, and this one answers to Prince Nazjak.$B$BHe is old naga royalty, $N. Proud, cruel, and clever, one of the drowned princes who remember Zin-Azshari as it was before the sea took it. While he lives the Spitelash will keep coming no matter how many we cut down.$B$BI am posting a bounty on his crowned head. Find him at the water''s heart and end him. Storm take his line.', `QuestCompletionLog` = 'Prince Nazjak slain.' WHERE `ID` = 300404;
UPDATE `quest_offer_reward` SET `RewardText` = 'Nazjak dead? HAH!$B$BThe tide turns, $N. Cut off the head and the serpent thrashes blind. You have earned this bounty and more. The Spitelash will not soon find another prince.' WHERE `ID` = 300404;
UPDATE `quest_template` SET `LogTitle` = 'Rations from the Reef', `LogDescription` = 'Collect 10 Tender Crab Meat.', `QuestDescription` = 'An army marches on its belly, $N, and mine is sick to death of salt-fish and hard bread.$B$BThe great river crabs are tough as boot leather, but there is good meat in them once the shell is off, and the crater has grown them fat.$B$BGather ten cuts of Tender Crab Meat from the shallows. Cook fires tonight, and my tide-guard eats like it earned it.', `QuestCompletionLog` = 'Ten cuts of Tender Crab Meat gathered.' WHERE `ID` = 300407;
UPDATE `quest_offer_reward` SET `RewardText` = 'It smells of low tide and looks worse.$B$BBut it is meat, and my soldiers will bless your name over the cook fire tonight. Good work, $N.' WHERE `ID` = 300407;
UPDATE `quest_template` SET `LogTitle` = 'Thieves Among the Ruins', `LogDescription` = 'Kill 8 Syndicate Prowlers and 8 Syndicate Conjurors.', `QuestDescription` = 'As if the naga were not trouble enough, now the Syndicate has crept into the ruins to pick the bones of Zin-Azshari.$B$BHuman thieves and their hedge-mages, $N. Prowlers with quick knives and Conjurors who fling fire from the shadows. They will sell whatever cursed relic they dig up to the worst buyer they can find.$B$BGo to the ruins. Kill eight Syndicate Prowlers and eight Syndicate Conjurors, and leave the dead as a warning to the rest.', `QuestCompletionLog` = 'Syndicate thieves cut down.' WHERE `ID` = 300408;
UPDATE `quest_offer_reward` SET `RewardText` = 'The ruins are quiet again, and the Syndicate is short a good many knives and wands.$B$BThey will think hard before they come looting my shore a second time. Well done, $N.' WHERE `ID` = 300408;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Molok the Crusher', `LogDescription` = 'Slay Molok the Crusher.', `QuestDescription` = 'There is a monster loose beyond the shore, $N, and even the naga give it a wide berth. Molok the Crusher, an ogre the size of a siege engine, with a temper to match.$B$BHe smashes flat everything that crosses his path, ours and theirs alike. A creature that big and that stupid answers to nothing but a killing blow.$B$BThe bounty is posted. Hunt Molok down and end his rampage before he wanders into my camp.', `QuestCompletionLog` = 'Molok the Crusher slain.' WHERE `ID` = 300409;
UPDATE `quest_offer_reward` SET `RewardText` = 'Molok is dead? HAH!$B$BA mighty kill, $N. That brute would have flattened half my bunkers given the chance. The bounty is yours, well earned. The whole shore breathes easier tonight.' WHERE `ID` = 300409;
UPDATE `quest_template` SET `LogTitle` = 'The Turned Timbermaw', `LogDescription` = 'Slay 10 Timbermaw Warriors and 8 Timbermaw Watchers.', `QuestDescription` = 'The Timbermaw once kept to their tunnels, $N. Placid, tribal, no concern of mine. But the crater''s raw arcane seeps into everything it touches, and the furbolgs of these woods have drunk deep of it. Their eyes have gone wrong. Their warriors and watchers now fall upon anything that draws breath.$B$BI have no interest in mending them; leave that sentiment to the priestess. I need the tainted specimens thinned before they trample my work into the mud. Cut down 10 Timbermaw Warriors and 8 Timbermaw Watchers, and be quick about it.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The corrupted furbolgs lie still.' WHERE `ID` = 300500;
UPDATE `quest_offer_reward` SET `RewardText` = 'You reek of furbolg, $C. Good. The specimens are quieted, and my instruments can hear themselves think again.' WHERE `ID` = 300500;
UPDATE `quest_template` SET `LogTitle` = 'Echoes of Zin-Azshari', `LogDescription` = 'Slay 8 Highborne Apparitions and 8 Highborne Lichlings.', `QuestDescription` = 'Do you feel them, $N? The air here is thick with the dead. When the Well collapsed and drowned Zin-Azshari, the Highborne did not all go cleanly into the dark. Their apparitions drift the ruins still, and worse things have knit themselves from their bones and their spite, lichlings that remember only hunger.$B$BFascinating, truly. But I cannot chart their patterns while they claw at every living thing that passes. Scatter 8 Highborne Apparitions and 8 Highborne Lichlings. Give me quiet ruins to study, not a screaming crypt.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Highborne echoes are scattered.' WHERE `ID` = 300501;
UPDATE `quest_offer_reward` SET `RewardText` = 'Undone, all of them, and their whispers with them. A pity, in a way. There was so much yet to learn from that old, proud grief. You have my thanks, $N.' WHERE `ID` = 300501;
UPDATE `quest_template` SET `LogTitle` = 'The Drowned Shrine', `LogDescription` = 'Slay 8 Spitelash Sirens and 8 Spitelash Myrmidons.', `QuestDescription` = 'The sea remembers Azshara, and it sends her children back to claim what the water took. A small shrine among the pools has been seized by the naga, $N, and their song carries on the damp air, sirens and their armored myrmidons coiling through the flooded halls.$B$BI will not have serpents nesting so near my wards. Break their hold. Kill 8 Spitelash Sirens and 8 Spitelash Myrmidons, and let the shrine fall silent again.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The naga song is silenced.' WHERE `ID` = 300502;
UPDATE `quest_offer_reward` SET `RewardText` = 'The song has stopped. The naga will not so easily forget this shrine, but for now the water flows without their poison. Well done.' WHERE `ID` = 300502;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Ragepaw', `LogDescription` = 'Slay Ragepaw.', `QuestDescription` = 'The tainted furbolgs do not act on madness alone, $N. One beast drives them, a great, scarred brute the pack calls Ragepaw. He is no leader by cunning; he is the largest teeth in the den, and the corruption sings loudest in him.$B$BSever the head and the body flails without purpose. Hunt Ragepaw down and put your blade through him. A camp without its tyrant is far easier to study.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Ragepaw is slain.' WHERE `ID` = 300503;
UPDATE `quest_offer_reward` SET `RewardText` = 'So the great Ragepaw bleeds like any other beast. The camp is leaderless and confused. Precisely as I predicted, $C.' WHERE `ID` = 300503;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Varo''then', `LogDescription` = 'Slay Varo''then''s Ghost.', `QuestDescription` = 'There is a tower among the ruins where the cold never lifts, and within it a shade that will not rest, $N. Captain Varo''then, Queen Azshara''s own champion, who marched to the Well of Eternity and never truly left it. Ten thousand years of ruin and still he stalks his post.$B$BI would bind such a spirit if I could. I cannot; he is too far gone, too full of hate. So end him. Face Varo''then''s Ghost and lay the old warrior down for good.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Varo''then''s Ghost is undone.' WHERE `ID` = 300504;
UPDATE `quest_offer_reward` SET `RewardText` = 'The champion of Azshara, dispersed at last by a lone $R. He would have found that intolerable. I find it merely useful. My thanks, $N.' WHERE `ID` = 300504;
UPDATE `quest_template` SET `LogTitle` = 'Into Haldarr Territory', `LogDescription` = 'Seek out Felsworn Kael''thos in Haldarr territory.', `QuestDescription` = 'My interests end where the satyrs begin, $N. To the west the ground turns rotten with fel, and the Haldarr and their demon-lords gather in numbers that trouble even me. That is a hunter''s problem, not a scholar''s.$B$BThere is one who wages that war already, a fel-touched tracker named Kael''thos. Felsworn, they call him, and for good reason. Seek him out in Haldarr territory and tell him what stirs in the crater. He will know what to do with it.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Speak with Felsworn Kael''thos.' WHERE `ID` = 300505;
UPDATE `quest_template` SET `LogTitle` = 'The Beast in the Deep', `LogDescription` = 'Slay Scalebeard in the Water Temple.', `QuestDescription` = 'Something ancient rests beneath the temple waters, $N. A great turtle the naga have suffered to live, Scalebeard, older than their intrusion and heavier than a warhorse. He guards those pools out of nothing but old, dumb instinct, and while he wallows there my people cannot reach what lies below.$B$BI have no quarrel with the beast''s age, only its inconvenience. Go down into the Water Temple and put Scalebeard to rest.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Scalebeard is slain.' WHERE `ID` = 300506;
UPDATE `quest_offer_reward` SET `RewardText` = 'The old beast is dead and the deep pools are ours to search. Something in me regrets it. Something larger does not. Good work, $N.' WHERE `ID` = 300506;
UPDATE `quest_template` SET `LogTitle` = 'Feathers of the Thunderhead', `LogDescription` = 'Collect 10 Hippogryph Feathers.', `QuestDescription` = 'The cliffs above are ruled by the Thunderhead hippogryphs, $N, and they are no ordinary beasts. The crater''s arcane has soaked into them just as it has the furbolgs and the dead, and it settles thickest in their plumage. Each feather hums with power I can bend to my instruments.$B$BClimb to their roosts and gather 10 Hippogryph Feathers for me. Mind their talons. Whatever the magic has done to them, it has not made them gentle.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = '10 Hippogryph Feathers gathered.' WHERE `ID` = 300507;
UPDATE `quest_offer_reward` SET `RewardText` = 'Yes. Yes, feel how they thrum. Ten feathers, each one saturated with the crater''s residue. This will advance my work considerably, $C. You have my gratitude.' WHERE `ID` = 300507;
UPDATE `quest_template` SET `LogTitle` = 'The Wailing Baroness', `LogDescription` = 'Defeat Baroness Anandara.', `QuestDescription` = 'This was a temple of Elune once, $N. Her light poured through these arches and blessed all who knelt here. Now a banshee sits enthroned where the altar stood, Baroness Anandara, and her wailing drowns out the Moon''s own voice. It grieves me beyond words to see such a place defiled.$B$BI cannot cleanse what she holds while she still rules it. Ascend to her seat and cast her down. Only when Anandara is destroyed can the light of Elune return to this house.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'Baroness Anandara is destroyed.' WHERE `ID` = 300510;
UPDATE `quest_template` SET `LogTitle` = 'The Web-Choked Halls', `LogDescription` = 'Defeat Nerub''enkan and Mother Smolderweb.', `QuestDescription` = 'The lower sanctuary is lost to us, $N, sealed behind a curtain of webbing thick as canvas. Two horrors spin it: Nerub''enkan, a wretched thing dragged up from the Scourge''s crypts, and Mother Smolderweb, whose brood boils out faster than any hand can clear.$B$BElune''s tears cannot reach ground so choked with poison and silk. Descend into the halls and slay them both. Cut out the spinners, and the webs will rot away in time.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'Nerub''enkan and Mother Smolderweb are slain.' WHERE `ID` = 300511;
UPDATE `quest_template` SET `LogTitle` = 'Grim Wanderers', `LogDescription` = 'Slay Skul and Tendris Warpwood.', `QuestDescription` = 'The corruption of this place draws the worst of Azeroth to its doors, $N. Two such wanderers stalk the temple grounds now: Skul, a hollow-eyed shade that hungers for the living, and Tendris Warpwood, an ancient of the forest twisted into something that would sicken the goddess who once shaped his kind.$B$BThey do not belong in Elune''s house, and they will not leave it willingly. Find Skul and Tendris Warpwood, and grant them the peace their torment denies them.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'Skul and Tendris Warpwood are at rest.' WHERE `ID` = 300512;
UPDATE `quest_template` SET `LogTitle` = 'The Defiled Sanctum', `LogDescription` = 'Slay 10 Corrupted Spectres and 8 Black Morass Tarantulas.', `QuestDescription` = 'Walk the inner sanctum with me a moment, $N, and tell me you do not weep. Where sisters once sang to the Moon, corrupted spectres drift and moan, and black tarantulas from some morass I dare not name nest in the very font of blessing. Every corner of this holy place has been made unclean.$B$BI cannot pray over ground so thickly haunted. Thin them for me. Destroy 10 Corrupted Spectres and 8 Black Morass Tarantulas, so that I may begin to hallow the sanctum anew.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'The sanctum''s defilers are thinned.' WHERE `ID` = 300513;
UPDATE `quest_template` SET `LogTitle` = 'Blight on Holy Ground', `LogDescription` = 'Slay 8 Plague Bats, 8 Plague Slimes, and 6 Bonelashers.', `QuestDescription` = 'The rot has gone beyond spirits and spiders, $N. It has crept into the living things themselves. The bats that once nested in the eaves now drip with plague, the very slimes underfoot carry it, and the bonelashers, oh, they were beasts of the wild once, before something unmade them.$B$BElune''s light cannot dwell where such sickness spreads unchecked. Purge it. Slay 8 Plague Bats, 8 Plague Slimes, and 6 Bonelashers, and give the Moon''s house one clean breath of air.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'The temple''s blight is cleansed.' WHERE `ID` = 300514;
UPDATE `quest_template` SET `LogTitle` = 'The Legashi Blight', `LogDescription` = 'Kill 10 Legashi Satyrs and 8 Legashi Rogues.', `QuestDescription` = 'You smell it too, don''t you, $N? Fel rot on the wind. I carry it in my own blood, so I know its stink better than any priest.$B$BThe Legashi were night elves once, before Xavius'' bargain twisted them into satyrs. Now they root themselves in this ground and spread their poison deeper with every night that passes. The horned warriors do the killing, and the rogues creep behind to finish what''s left.$B$BGo out among them and cut them down. Ten of the satyrs, eight of the rogues. Do not hesitate. I never do.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Legashi are thinned.' WHERE `ID` = 300600;
UPDATE `quest_template` SET `LogTitle` = 'Jadefire Grown Bold', `LogDescription` = 'Kill 8 Jadefire Tricksters and 8 Jadefire Felsworn.', `QuestDescription` = 'The Jadefire clan grows brazen, $N. Where the Legashi skulk, the Jadefire march openly, drunk on the crater''s leaking power.$B$BTheir tricksters weave illusions to lead the unwary onto their blades, and their felsworn... their felsworn have surrendered themselves whole to the Legion. I know that road. I walk its edge every waking hour, and I will not let them think it easy.$B$BStrike down eight of their tricksters and eight of their felsworn. Teach them that boldness here has a price.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Jadefire''s boldness is broken.' WHERE `ID` = 300601;
UPDATE `quest_template` SET `LogTitle` = 'Breaking the Watch', `LogDescription` = 'Kill 8 Felguard Sentinels and 10 Felhounds.', `QuestDescription` = 'The Legion does not simply raid this place, $N. It garrisons it. Felguard sentinels stand posted at the pit''s approaches, and packs of felhounds prowl the ground between them, sniffing out any magic that stirs.$B$BSo long as their watch holds, nothing we do here goes unseen. I have felt those hounds catch my scent. I do not care to feel it again.$B$BBreak their line. Slay eight of the felguard sentinels and ten of the felhounds. Blind the pit''s eyes for a while.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Legion''s watch is broken.' WHERE `ID` = 300602;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Monnos the Elder', `LogDescription` = 'Slay Monnos the Elder.', `QuestDescription` = 'There is an old fire that walks this crater, $N. Monnos the Elder, the satyrs call him, and they feed him. An ancient elemental of living flame, older than the corruption that stains this ground.$B$BEverything he touches blackens and burns, and the fel-things gather to his heat like moths. I have hunted many horrors here, but this one I have left standing too long.$B$BFind Monnos and put him out. A hunter finishes what he starts.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Monnos the Elder is extinguished.' WHERE `ID` = 300604;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Solenor the Slayer', `LogDescription` = 'Slay Solenor the Slayer.', `QuestDescription` = 'I would speak plainly with you, $N, because Solenor and I are cut from the same corrupted cloth.$B$BHe was a hunter of demons once, until the hunt hollowed him out and the pit filled what was left. Now he stalks the Haldarr grounds, tearing open portals to loose more of the Legion into this world. He is what I might yet become, and that is why he must fall before I do.$B$BHunt him down in Haldarr. Bring the slayer low, and shut the doors he has opened.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Solenor the Slayer has fallen.' WHERE `ID` = 300605;
UPDATE `quest_offer_reward` SET `RewardText` = 'The portals flicker and fade. You have bought us time, $N. And you have shown me that even the far-gone can still be brought down. I will remember that.' WHERE `ID` = 300605;
UPDATE `quest_template` SET `LogTitle` = 'To the Dragon Coast', `LogDescription` = 'Find Dragonbinder Seryth on the coast.', `QuestDescription` = 'Word has come up from the coast, $N. Dragons on the shore, and the crater''s arcane bleed drawing them like blood draws sharks.$B$BThe blue flight does not wander here for nothing, and the satyrs have taken notice too. Dragonbinder Seryth holds the line down there and needs hands she can trust more than she needs mine. My kind unsettles the drakes.$B$BMake your way to the coast and find Seryth. Whatever is stirring on that shore, she will know the shape of it.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Seek out Dragonbinder Seryth on the coast.' WHERE `ID` = 300606;
UPDATE `quest_offer_reward` SET `RewardText` = 'Crude, but effective weaponry. So this is how the satyrs arm themselves against the drakes. We know their methods now, and knowing is half the hunt. Kael''thos chose well in sending you.' WHERE `ID` = 300606;
UPDATE `quest_template` SET `LogTitle` = 'Killers in the Dark', `LogDescription` = 'Kill 8 Jadefire Betrayers and 6 Jadefire Shadowstalkers.', `QuestDescription` = 'Not all the Jadefire meet you face to face, $N. The worst of them wait in the dark.$B$BTheir betrayers were sentinels and scouts once, night elves who sold their own kind for the Legion''s favor, and I hate them more than any demon born to the pit. Their shadowstalkers slip between the trees and open throats before a blade is even drawn.$B$BGo into the shadow and find them first. Eight betrayers, six shadowstalkers. Let them learn what it is to be hunted.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The shadow-killers are hunted down.' WHERE `ID` = 300607;
UPDATE `quest_template` SET `LogTitle` = 'Fires That Walk', `LogDescription` = 'Kill 10 Burning Felhounds.', `QuestDescription` = 'The satyrs have bred their hounds into something worse, $N. Burning felhounds, their veins run with green fire, and everything they pass through catches and smolders.$B$BThey are loosed to torch the wilds and drive out anything that will not bow to the pit. I have watched whole thickets go up in that sickly flame. This land has burned enough.$B$BHunt down ten of the burning felhounds and put their fires out for good.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The burning felhounds are put down.' WHERE `ID` = 300608;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Lethtendris', `LogDescription` = 'Slay Lethtendris.', `QuestDescription` = 'There is a witch among the satyrs, $N, and her name is Lethtendris.$B$BShe wields dark magic that even the felsworn fear, binding demons and rot to her will and setting them loose upon anything that draws breath in this crater. Where she treads, the corruption deepens and does not heal.$B$BI have marked her for the kill. Find Lethtendris and end her sorcery before she twists this land past all saving.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Lethtendris has been slain.' WHERE `ID` = 300609;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Obsidion', `LogDescription` = 'Slay Obsidion.', `QuestDescription` = 'At the heart of it all stands Obsidion, $N. A shadowguard warped past recognition, set to watch over the inner sanctum where the deepest corruption festers.$B$BNothing passes him. I have tried, and I bear the marks of it. Whatever the satyrs and their demon masters are hiding beyond his post, they guard it with everything they have.$B$BBreak through and destroy him. Shatter Obsidion, and open the way to whatever waits within.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Obsidion has been shattered.' WHERE `ID` = 300610;
UPDATE `quest_template` SET `LogTitle` = 'The Unquiet Coast', `LogDescription` = 'Kill 10 Kirin''Var Ghosts and 8 Ethereal Scavengers.', `QuestDescription` = 'I keep watch over the drakes and the surges, $N, but the dead along this coast are my burden too. The arcane bleeding out of the crater will not let them lie still. Kirin''Var Ghosts drift where their bodies fell, and Ethereal Scavengers pick at what magic clings to their bones.$B$BThey feel no peace, and while they linger they draw yet more corruption to them. Go to the shore and give them the only mercy left. Ten of the ghosts, and eight of the scavengers that torment them.', `AreaDescription` = 'The haunted coast, Azshara Crater', `QuestCompletionLog` = 'The coast is quiet once more.' WHERE `ID` = 300700;
UPDATE `quest_offer_reward` SET `RewardText` = 'You have a steady hand for grim work, $N. The dead rest, and the coast breathes easier for it. So do I.' WHERE `ID` = 300700;
UPDATE `quest_template` SET `LogTitle` = 'Unbound and Burning', `LogDescription` = 'Destroy 10 Mana Surges.', `QuestDescription` = 'Feel that on the air? That is raw magic with nowhere to go. When the Well drowned Zin-Azshari, it left a wound in this land that has never closed, and the power still seeping from it gathers, twists, and takes shape as Mana Surges.$B$BLeft alone they grow, and what they touch, they warp. I have watched whelps and worse rise from that same unbound energy. Ground them out before they spread, $N. Ten of the surges should thin them enough to matter.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The surges are scattered.' WHERE `ID` = 300701;
UPDATE `quest_offer_reward` SET `RewardText` = 'Good. Every surge you dissipate is one less thing feeding on this crater''s madness. Keep that up and we might yet hold this ground.' WHERE `ID` = 300701;
UPDATE `quest_template` SET `LogTitle` = 'The Corrupted Brood', `LogDescription` = 'Kill 8 Corrupted Blue Whelps.', `QuestDescription` = 'It shames me to send you against them, $N. I am a warden of dragonkind, and the blue flight are meant to be the keepers of magic itself. But the crater''s poison has reached even the youngest of them. The Corrupted Blue Whelps no longer know their own purpose. They lash out at anything living, blind with tainted power.$B$BThere is no healing this. Not for these. Cull eight of the corrupted whelps and let the flight mourn what it has lost. I will mourn with them.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Eight of the corrupted brood lie still.' WHERE `ID` = 300702;
UPDATE `quest_offer_reward` SET `RewardText` = 'A hard thing, done cleanly. The flight will not thank you, but I do. Better they die whelps than grow into something the corruption fully owns.' WHERE `ID` = 300702;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Nexus-Prince Shaffar', `LogDescription` = 'Kill Nexus-Prince Shaffar.', `QuestDescription` = 'The rot in the whelps and the surges did not come from nowhere, $N. It has a hand guiding it. Nexus-Prince Shaffar, an ethereal schemer, has bent the leaking arcane of this place to his own designs and made himself its master.$B$BStrike the head from this and the body weakens. He will not face you fairly, so face him without mercy. Kill Nexus-Prince Shaffar, and much of the corruption here loses its shepherd.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Shaffar''s scheming is ended.' WHERE `ID` = 300703;
UPDATE `quest_offer_reward` SET `RewardText` = 'So the prince is dead. I can already feel the corruption fraying at the edges without his will to shape it. Well struck, $N.' WHERE `ID` = 300703;
UPDATE `quest_template` SET `LogTitle` = 'March on the Temple', `LogDescription` = 'Report to Archmage Thadeus at the Temple of Eternity.', `QuestDescription` = 'The fight moves beyond my drakes and my dead now, $N. Everything converging on this crater is drawn to one place in the end: the Temple of Eternity, where the old Highborne once reached too far and paid for it.$B$BArchmage Thadeus commands what stand we can muster there, and he will need every capable hand. I can hold the coast. You are needed at the temple. Report to Archmage Thadeus and lend him your strength.', `AreaDescription` = 'The Temple of Eternity, Azshara Crater', `QuestCompletionLog` = 'Seek Archmage Thadeus at the temple.' WHERE `ID` = 300704;
UPDATE `quest_template` SET `LogTitle` = 'Orders in the Dark', `LogDescription` = 'Collect 6 Cultist Orders.', `QuestDescription` = 'The cultists infesting these ruins are not the mindless sort, $N. The Shadow Council and the Kil''sorrow scheme with purpose, and they put that purpose to paper. Every raiding party and every summoning ritual answers to written orders passed down their ranks.$B$BGet me those orders and I will know their next move before they make it. Take six sets of Cultist Orders from the cultists themselves. Cut them down and search the bodies.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Six sets of Cultist Orders are in hand.' WHERE `ID` = 300706;
UPDATE `quest_offer_reward` SET `RewardText` = 'Let me see them. Yes... this tells me where they mean to strike next, and how thin they are spread. You have bought us the one thing this crater rarely gives, $N: warning.' WHERE `ID` = 300706;
UPDATE `quest_template` SET `LogTitle` = 'The Starving Threshold', `LogDescription` = 'Kill 8 Mana Seekers and 8 Drained Phase Hunters.', `QuestDescription` = 'You cannot simply walk into the Temple of Eternity, $N. Its very threshold crawls with things that hunger for the magic bleeding out of the ruins. Mana Seekers swarm the entrance in famished packs, and Drained Phase Hunters flicker in and out of sight, maddened by their own emptiness.$B$BThey will tear apart anyone who tries to pass while they still draw breath. Clear the threshold before our people advance. Eight of the Mana Seekers, and eight of the Drained Phase Hunters.', `AreaDescription` = 'The temple threshold, Azshara Crater', `QuestCompletionLog` = 'The temple threshold is clear.' WHERE `ID` = 300707;
UPDATE `quest_offer_reward` SET `RewardText` = 'The way in is open, and no one bled for it but the things that deserved to. That is as clean as this crater lets a fight be, $N.' WHERE `ID` = 300707;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Voidhunter Yar', `LogDescription` = 'Slay Voidhunter Yar.', `QuestDescription` = 'Something worse than a scavenger stalks the ruins now, $N. Voidhunter Yar is a voidwalker of terrible strength, called up from the emptiness between worlds and set loose to hunt whatever lives here. It has already dragged good scouts into the dark.$B$BThings born of the Void do not belong on this side of it. Find Yar, break its hold on this world, and banish it back to the nothing that spawned it.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Yar has been driven back into the Void.' WHERE `ID` = 300708;
UPDATE `quest_offer_reward` SET `RewardText` = 'Gone, back to the emptiness where it belongs. The ruins feel less watched already. You have the gratitude of every scout who will now come home, $N.' WHERE `ID` = 300708;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Doomsayer Jurim', `LogDescription` = 'Slay Doomsayer Jurim.', `QuestDescription` = 'The cultists follow a voice, $N, and that voice is Doomsayer Jurim. A fanatic to the marrow, he screams his prophecies of ending over the ruins and whips his followers into a frenzy that no reason can cool. As long as he raves, the cultists rave with him.$B$BSilence him, and you silence half their zeal. Find Doomsayer Jurim among his flock and end his doomsaying for good.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Jurim''s prophecies have gone quiet.' WHERE `ID` = 300709;
UPDATE `quest_offer_reward` SET `RewardText` = 'The screaming has stopped, and I can hear his followers falter without it. His doom never came for us, $N. It came for him.' WHERE `ID` = 300709;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Marticar', `LogDescription` = 'Slay Marticar.', `QuestDescription` = 'Not every threat in this crater is a scheme or a spirit, $N. Some are simply beasts grown too bold. Marticar is a great strider, warped larger and meaner than its kind should ever be, and it has taken to raiding the paths our supplies must cross.$B$BStarve us and the whole foothold falters. I have no patience left for it. Hunt down Marticar and put the beast down before it bleeds us of what little we haul in.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Marticar has been put down.' WHERE `ID` = 300710;
UPDATE `quest_offer_reward` SET `RewardText` = 'The beast will trouble our supply lines no more. A warden knows when a creature is past saving, $N, and that one was. Good hunting.' WHERE `ID` = 300710;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Collidus the Warp-Watcher', `LogDescription` = 'Slay Collidus the Warp-Watcher.', `QuestDescription` = 'We are watched, $N. Not by scouts or scrying, but by Collidus the Warp-Watcher, a beholder whose every unblinking eye drinks in our movements and reports them to worse things. So long as it stares, we have no secrets and no surprise.$B$BI want it blind. Seek out Collidus in the ruins and put out those eyes for good. Let the enemy grope in the dark for a change.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The Warp-Watcher sees no more.' WHERE `ID` = 300711;
UPDATE `quest_offer_reward` SET `RewardText` = 'Blinded at last. For the first time in weeks we can move without a hundred eyes tracking every step. That is worth more than you know, $N.' WHERE `ID` = 300711;
UPDATE `quest_template` SET `LogTitle` = 'Two Who Will Not Fade', `LogDescription` = 'Slay Speaker Mar''grom and the Avatar of the Martyred.', `QuestDescription` = 'The dead of this crater usually go quietly once released, $N. Two will not. Speaker Mar''grom and the Avatar of the Martyred cling to this world with a will that outlasts their flesh, feeding on the arcane wound the way the whelps and surges do. They have become more than restless. They have become anchors for the corruption around them.$B$BThere is no reasoning with grief this old and this twisted. Grant them the oblivion they refuse to seek. Lay Speaker Mar''grom and the Avatar of the Martyred to rest, whatever it takes.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Both spirits have been laid to rest.' WHERE `ID` = 300712;
UPDATE `quest_offer_reward` SET `RewardText` = 'They are gone, both of them, and the air where they lingered is lighter for it. You have done what neither prayer nor time could, $N. Let them finally sleep.' WHERE `ID` = 300712;
UPDATE `quest_template` SET `LogTitle` = 'Ranks of the Blighted', `LogDescription` = 'Destroy 12 Blighted Corpses.', `QuestDescription` = 'I have fought the Scourge on a dozen fronts, $N, and everywhere the story is the same: our fallen do not stay fallen. Even here, in the shadow of the Highborne sanctum, they stitch new soldiers from the dead.$B$BThese Blighted Corpses are the front rank of that dark work. Cut them down before the necromancers can raise them again. Twelve of them, put back into the dust where they belong.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'The blighted ranks are broken.' WHERE `ID` = 300800;
UPDATE `quest_offer_reward` SET `RewardText` = 'The skeletons are dusted, and the ground is ours to hold a while longer. Well struck, $N.' WHERE `ID` = 300800;
UPDATE `quest_template` SET `LogTitle` = 'Rest for the Moonrest', `LogDescription` = 'Lay to rest 8 Moonrest Highborne.', `QuestDescription` = 'Look upon them and grieve, $N. The Moonrest Highborne were sorcerers of Azshara''s old court, dust for ten thousand years. Now the Scourge has torn their spirits from slumber and set them shambling as spectral thralls.$B$BThere is no cruelty like waking the ancient dead to serve a colder death. Grant these eight the rest that was stolen from them. It is mercy, not slaughter.', `QuestCompletionLog` = 'The Highborne are silenced at last.' WHERE `ID` = 300801;
UPDATE `quest_template` SET `LogTitle` = 'Masters of the Risen', `LogDescription` = 'Slay 4 Shadowy Necromancers.', `QuestDescription` = 'Kill the risen and they simply rise again, $N. The strength of this incursion is not in its corpses but in the hands that command them. Four Shadowy Necromancers move among the sanctum''s ruins, and every soldier we destroy they raise anew.$B$BFind those four and end them. Break the will behind the horde, and the horde itself falls apart. I have seen it work on a hundred battlefields.', `QuestCompletionLog` = 'The necromancers command nothing now.' WHERE `ID` = 300802;
UPDATE `quest_template` SET `LogTitle` = 'Bounty: Gondria, the Spectral Stalker', `LogDescription` = 'Slay Gondria.', `QuestDescription` = 'There is a beast loose in the ruins that even my spellbreakers will not track. Gondria, they call it, a spectral stalker that pads through the sanctum on paws of cold light, restless and grieving in the way only a broken spirit can be.$B$BI will not pretend this is a mercy, $N. It is a bounty. The creature is dangerous and its torment must end. Hunt Gondria down and grant it the peace it cannot find on its own.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Gondria haunts the ruins no longer.' WHERE `ID` = 300803;
UPDATE `quest_offer_reward` SET `RewardText` = 'Gondria fades into the mist, and the ruins are quieter for it. The bounty is yours, well earned.' WHERE `ID` = 300803;
UPDATE `quest_template` SET `LogTitle` = 'Relics of the Sanctum', `LogDescription` = 'Recover 10 Ancient Artifacts.', `QuestDescription` = 'Before the Scourge grinds this place to rubble, there is knowledge here worth saving. The Highborne left Ancient Artifacts scattered through the temple, relics of an arcane mastery even the Kirin Tor has not fully recovered.$B$BSlip past the risen and gather ten of them for me, $N. Better they rest in my study than shatter beneath the boots of the dead. Some of these secrets we cannot afford to lose twice.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Ten artifacts saved from the Scourge.' WHERE `ID` = 300804;
UPDATE `quest_offer_reward` SET `RewardText` = 'Exquisite work. These belong in a proper study, safe from the rot outside. You have preserved more than you know, $N.' WHERE `ID` = 300804;
UPDATE `quest_template` SET `LogTitle` = 'Unbind the Phantoms', `LogDescription` = 'Collect 8 Phantom Essences.', `QuestDescription` = 'The phantoms drifting through the sanctum are not free spirits, $N. Each is chained to this world by a knot of Phantom Essence, a residue the necromancers use as a leash. So long as the essence holds, the dead cannot rest and we cannot advance.$B$BGather eight measures of that essence and bring it to me. In my hands the bindings unravel. In theirs, the dead march. It is that simple.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'Eight essences gathered for unbinding.' WHERE `ID` = 300805;
UPDATE `quest_offer_reward` SET `RewardText` = 'The essence dissipates in my hands, and the spirits it bound drift free at last. A good day''s work against a patient enemy.' WHERE `ID` = 300805;
UPDATE `quest_template` SET `LogTitle` = 'Lady of the Drowned Court', `LogDescription` = 'Defeat Lady Sarevess.', `QuestDescription` = 'Study these ruins long enough and the past begins to answer back, $N. Zin-Azshari was the seat of Queen Azshara''s Highborne before the Sundering swallowed it, and its old blood has come crawling home. The naga here answer to one of their own kind: Lady Sarevess.$B$BShe is Highborne turned serpent, proud and deadly, and she means to make this drowned court hers again. I cannot record what I cannot reach. Defeat Sarevess, and let me walk these ruins in peace.', `AreaDescription` = 'Ruins of Zin-Azshari', `QuestCompletionLog` = 'Lady Sarevess commands the ruins no more.' WHERE `ID` = 300900;
UPDATE `quest_offer_reward` SET `RewardText` = 'Sarevess is finished, and the ruins are still again. Now, perhaps, they will give up their secrets to me instead of their intruders.' WHERE `ID` = 300900;
UPDATE `quest_template` SET `LogTitle` = 'The Dread Warleader', `LogDescription` = 'Slay Targorr the Dread.', `QuestDescription` = 'The naga are not the only claimants to these stones, $N. A warband of Blackrock Orcs has driven its stakes into Zin-Azshari, and while they hold it, my work here is impossible. They answer to a brute called Targorr the Dread.$B$BHe is exactly as subtle as his name suggests. Cut down Targorr and the rest will lose their nerve and their footing both. I am a magister, not a soldier, so this task falls to you.', `AreaDescription` = 'Ruins of Zin-Azshari', `QuestCompletionLog` = 'Targorr the Dread has fallen.' WHERE `ID` = 300901;
UPDATE `quest_offer_reward` SET `RewardText` = 'Targorr is dead, and the Blackrock will crumble without a hand to drive them. My thanks, $N. The ruins are mine to study again.' WHERE `ID` = 300901;
UPDATE `quest_template` SET `LogTitle` = 'Silence the Death Speaker', `LogDescription` = 'Defeat Death Speaker Jargba.', `QuestDescription` = 'Sit a moment, $N, and hear an old furbolg out. The crater''s poison seeps into everything it touches, and it has found its way into the Timbermaw Deep, our own sacred hollow. Where it takes root, it needs a voice, and that voice is the Death Speaker, Jargba.$B$BHe whispers the corruption into my kin and turns brother against brother. My paws are too old for this fight, but yours are not. Go into the Deep and silence Jargba before his words claim any more of my people.', `AreaDescription` = 'Timbermaw Deep', `QuestCompletionLog` = 'The Death Speaker whispers no more.' WHERE `ID` = 300910;
UPDATE `quest_offer_reward` SET `RewardText` = 'The whispering has stopped. My people can sleep peacefully now, $N. An old furbolg does not forget a kindness like this. Thank you.' WHERE `ID` = 300910;
UPDATE `quest_template` SET `LogTitle` = 'The Thorncurse Betrayal', `LogDescription` = 'Slay Aggem Thorncurse.', `QuestDescription` = 'It grieves me more than the Scourge or the naga ever could, $N, for this wound comes from within. Aggem Thorncurse was of the Timbermaw once, kin of mine, before the crater''s rot hollowed him out and turned him to lead the assault against his own.$B$BThere is no reasoning left in him, only the corruption wearing his face. Find Aggem and end him. It is not a thing I ask lightly of anyone, but a traitor loose in the Deep is a knife at every throat here.', `AreaDescription` = 'Timbermaw Deep', `QuestCompletionLog` = 'Aggem Thorncurse betrays us no longer.' WHERE `ID` = 300911;
UPDATE `quest_offer_reward` SET `RewardText` = 'Aggem is dead. A fitting end for one who turned on his own kin. Grieve him I may, but the Deep is safer for it, $N.' WHERE `ID` = 300911;
UPDATE `quest_template` SET `LogTitle` = 'The Mosshide Menace', `LogDescription` = 'Slay 8 Mosshide Brutes and 8 Mosshide Mystics.', `QuestDescription` = 'As if the rot within were not burden enough, the Mosshide gnolls have crept into our sacred cave and fouled it with their filth, $N. They are scavengers drawn to weakness, and they smell it on us now.$B$BThey come in two shapes: the Brutes who break what they cannot carry, and the Mystics who twist what little magic they can steal. Drive out eight of each. Let the Mosshide learn that even a wounded Timbermaw still has claws.', `AreaDescription` = 'Timbermaw Deep', `QuestCompletionLog` = 'The Mosshide have been driven from the cave.' WHERE `ID` = 300912;
UPDATE `quest_offer_reward` SET `RewardText` = 'The cave breathes cleaner now, though the stench of gnoll may linger a while yet. You have my thanks, $N, and that of the whole Timbermaw.' WHERE `ID` = 300912;
UPDATE `quest_template` SET `LogTitle` = 'Loregrain''s Last Ember', `LogDescription` = 'Defeat Pyromancer Loregrain.', `QuestDescription` = 'By me beard, $N, this was meant to be an honest excavation until the Dark Iron came crawling up from below. Their firestarter, Pyromancer Loregrain, leads the whole rotten column, and every tunnel he touches goes up in flame.$B$BGet down into the Spitelash Depths and put his fire out for good. A prospector can''t work a claim with the whole vein burning around him.', `AreaDescription` = 'Spitelash Depths', `QuestCompletionLog` = 'Loregrain is ash.' WHERE `ID` = 300920;
UPDATE `quest_offer_reward` SET `RewardText` = 'Ha! Loregrain''s naught but ash and cinders now. Without their firestarter to light the way, those Dark Iron will scatter back down their holes.' WHERE `ID` = 300920;
UPDATE `quest_template` SET `LogTitle` = 'Break the Iron Ranks', `LogDescription` = 'Slay 10 Dark Iron Watchmen and 10 Dark Iron Geologists.', `QuestDescription` = 'Every day I swing me pick, another Dark Iron crew claws closer to the surface. Their Watchmen guard the tunnels while their Geologists sniff out the very veins I''ve been surveyin'' for weeks. The nerve of ''em, $N!$B$BThin their numbers before the whole lot breaks into daylight. Slay ten Dark Iron Watchmen and ten Dark Iron Geologists, and remind them whose claim this is.', `AreaDescription` = 'Spitelash Depths', `QuestCompletionLog` = 'The Iron ranks are thinned.' WHERE `ID` = 300921;
UPDATE `quest_offer_reward` SET `RewardText` = 'Twenty fewer picks scratchin'' at me claim. That''s a good day''s work, $N. Let the Dark Iron think twice before they crawl up into the light again.' WHERE `ID` = 300921;
UPDATE `quest_template` SET `LogTitle` = 'Faulty Engineering', `LogDescription` = 'Destroy the Faulty War Golem.', `QuestDescription` = 'Now here''s a curious bit of shoddy craftsmanship, $N. The Dark Iron built themselves a great War Golem to guard the forge chambers, but their smithing was sloppy work — its core runs hot and unstable, like to blow at any moment.$B$BStrike it down before it wanders up into me dig and takes half the mountain with it. And mind the blast when it goes.', `AreaDescription` = 'Spitelash Depths', `QuestCompletionLog` = 'The War Golem is scrap.' WHERE `ID` = 300922;
UPDATE `quest_offer_reward` SET `RewardText` = 'Down it went in a fine shower of sparks! Shoddy build, that golem — but the metal''s good iron underneath. We''ll salvage what parts we can and put ''em to honest use.' WHERE `ID` = 300922;
UPDATE `quest_template` SET `LogTitle` = 'Ambassador of Flame', `LogDescription` = 'Slay Ambassador Flamelash.', `QuestDescription` = 'This is no longer a matter of trespassin'', $N. The Dark Iron have called up a lord of living fire — Ambassador Flamelash himself — and he means to tear open a door to the Firelands right beneath our feet.$B$BI''m a prospector, not a warrior, but even I know what comes if that portal opens. Banish Flamelash back to the flames that spawned him, before this whole crater becomes a second Firelands.', `AreaDescription` = 'Spitelash Depths', `QuestCompletionLog` = 'Flamelash is banished.' WHERE `ID` = 300923;
UPDATE `quest_offer_reward` SET `RewardText` = 'The portal guttered out the moment he fell. Flamelash is banished — for now, at least. You''ve bought us time, $N, and maybe saved the whole excavation with it.' WHERE `ID` = 300923;
UPDATE `quest_template` SET `LogTitle` = 'Blackrock Incursion', `LogDescription` = 'Slay 12 Blackrock Soldiers or Slayers.', `QuestDescription` = 'You feel the heat rising off the Searing Pit, $N? That is the breath of the Blackrock horde. They have seized this ground as a staging pit for something far darker, and their soldiers hold the line while it festers behind them.$B$BTake up your blade and cut through them. Slay twelve of their Soldiers or Slayers, and let the rest learn that a reckoning is coming for this pit.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'The Blackrock line is broken.' WHERE `ID` = 300930;
UPDATE `quest_offer_reward` SET `RewardText` = 'Twelve cut down, and the line breaks. Good. Every Blackrock that falls here is one fewer between my blade and the thing they serve below.' WHERE `ID` = 300930;
UPDATE `quest_template` SET `LogTitle` = 'Spirestone Menace', `LogDescription` = 'Slay 10 Spirestone Ogres (Mystics, Lords, or Butchers).', `QuestDescription` = 'The Blackrock do not fight alone, $N. They have bought the muscle of the Spirestone ogres — Mystics who chant to the flame, Lords who drive the brutes, Butchers who do the ugly work. Together they are the fist that holds this pit closed against us.$B$BBreak that fist. Crush ten of the Spirestone ogres, whatever their kind, and the Blackrock will find themselves suddenly short of strength.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'The Spirestone ogres are crushed.' WHERE `ID` = 300931;
UPDATE `quest_offer_reward` SET `RewardText` = 'Ten ogres, broken and scattered. The Blackrock lean on that Spirestone muscle more than they know. Take it from them, $N, and the whole rotten structure starts to sag.' WHERE `ID` = 300931;
UPDATE `quest_template` SET `LogTitle` = 'Beasts of the Pit', `LogDescription` = 'Slay 10 Giant Ember Worgs or Tar Creepers.', `QuestDescription` = 'The pit corrupts everything it touches, $N — even the beasts. The Giant Ember Worgs run with fire in their veins now, and the Tar Creepers were dragged up from some black seam and set loose as living traps.$B$BThey are past saving. Put ten of them down, worg or creeper, and grant these poor twisted things the mercy of a clean death.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'The corrupted beasts are put down.' WHERE `ID` = 300932;
UPDATE `quest_offer_reward` SET `RewardText` = 'It is grim work, slaying beasts that never chose this fate. But mercy is a blade too, $N, and you have wielded it well. The pit will make more — it always does.' WHERE `ID` = 300932;
UPDATE `quest_template` SET `LogTitle` = 'Ambassador''s End', `LogDescription` = 'Slay Ambassador Flamelash.', `QuestDescription` = 'So the Dark Iron have sent their fire-lord to us as well. Ambassador Flamelash commands their presence in the Searing Pit, and while he burns, the Blackrock will never yield this ground.$B$BI have hunted demons and elementals both, $N, and this one dies the same as the rest — by the blade, and without mercy. Send Flamelash screaming back to the Firelands.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'Flamelash is undone.' WHERE `ID` = 300933;
UPDATE `quest_offer_reward` SET `RewardText` = 'He returns to the fire that made him, and good riddance. With their fire-lord gone, the Dark Iron here are just dwarves with hot tempers. Dwarves we can deal with.' WHERE `ID` = 300933;
UPDATE `quest_template` SET `LogTitle` = 'The Dark Iron General', `LogDescription` = 'Defeat General Angerforge.', `QuestDescription` = 'Every rabble needs a mind to make it an army, $N, and the Blackrock have theirs: General Angerforge. It is his discipline that forges this howling mob into a fighting force, his commands that keep the pit sealed against us.$B$BCut off the head. Defeat Angerforge, and the war-machine he built will fall apart in confusion. Then the true cleansing can begin.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'Angerforge is defeated.' WHERE `ID` = 300934;
UPDATE `quest_offer_reward` SET `RewardText` = 'Angerforge ruled that host with an iron fist — and now the fist is broken. Without him the Blackrock are a mob again, snapping at shadows. Leaderless, and ripe for the reckoning.' WHERE `ID` = 300934;
UPDATE `quest_template` SET `LogTitle` = 'Terrors from the Deep', `LogDescription` = 'Defeat Hydrospawn.', `QuestDescription` = 'The pit''s corruption has seeped into the very water table, $N, and something has answered from below. A great elemental — Hydrospawn, the diggers name it — rises where the fire and the flood meet, and all it touches drowns or burns.$B$BI''ll not have such a horror at my back while I fight the Blackrock. Go down and defeat Hydrospawn before it grows past all stopping.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'Hydrospawn is destroyed.' WHERE `ID` = 300935;
UPDATE `quest_offer_reward` SET `RewardText` = 'The waters go still, and the horror sinks back into the dark it crawled from. Hydrospawn is no more. One less terror clawing up from the deep, $N — though never doubt the pit will breed another.' WHERE `ID` = 300935;
UPDATE `quest_template` SET `LogTitle` = 'Warlord of the Pit', `LogDescription` = 'Defeat Ghok Bashguud.', `QuestDescription` = 'This is the one, $N. Ghok Bashguud — warlord of the Searing Pit, the iron fist that every Blackrock and Dark Iron here answers to. All our work has led us to his door.$B$BI have waited a long time to face him blade to blade. Come with me, or come after — but come. Together we end his reign, and the pit falls silent at last.', `AreaDescription` = 'The Searing Pit', `QuestCompletionLog` = 'Ghok Bashguud has fallen.' WHERE `ID` = 300936;
UPDATE `quest_offer_reward` SET `RewardText` = 'It is done. Ghok Bashguud lies dead, and for one shining moment the Searing Pit is ours to command. Savor it, $N — the pit never stays quiet for long, but today, today we won.' WHERE `ID` = 300936;
UPDATE `quest_template` SET `LogTitle` = 'The Fallen Priestess', `LogDescription` = 'Defeat Priestess Delrissa.', `QuestDescription` = 'Look upon what has become of this holy place, $N. The Temple of Elune was raised to honor the Moon''s mercy, and now its halls run thick with corruption. Priestess Delrissa presides over the defilement.$B$BShe was a devoted sister of our order once, her voice among the sweetest in prayer. Whatever whispered to her in the dark has hollowed that soul away. I cannot save her now, but you can end her suffering and stop the rot from spreading further. Go, and may Elune steady your hand.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'Priestess Delrissa lies defeated.' WHERE `ID` = 300940;
UPDATE `quest_offer_reward` SET `RewardText` = 'Priestess Delrissa... she was once a noble soul, luminous with the Moon''s grace. You have given her the peace I could not, $N. Elune remembers this service.' WHERE `ID` = 300940;
UPDATE `quest_template` SET `LogTitle` = 'The Twilight Lord', `LogDescription` = 'Slay Twilight Lord Kelris.', `QuestDescription` = 'The corruption did not take root on its own, $N. Twilight''s Hammer crept into these halls while we mourned, and their master here is Twilight Lord Kelris. It is his cult that feeds the shadow gnawing at the temple.$B$BCut off the head and the body will falter. Find Kelris and silence his dark sermons for good.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'Twilight Lord Kelris is slain.' WHERE `ID` = 300941;
UPDATE `quest_offer_reward` SET `RewardText` = 'Kelris will preach no more. With their leader gone, the cultists scatter like shadows before the dawn. You have my thanks, $N.' WHERE `ID` = 300941;
UPDATE `quest_template` SET `LogTitle` = 'The Arcane Torrent', `LogDescription` = 'Defeat Arcane Torrent.', `QuestDescription` = 'Elune''s light is not the only power that lingers here. This crater still bleeds the wild arcane of the drowned Well, and where it pools it takes shape. The thing we name Arcane Torrent tears at the wards that hold this sanctuary together.$B$BIf it is not unmade, the last of our protections will fail and the temple will lie open to every horror in the crater. Destroy it, $N, before that day comes.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'Arcane Torrent is undone.' WHERE `ID` = 300942;
UPDATE `quest_offer_reward` SET `RewardText` = 'The Torrent is undone, and I feel the wards drawing breath once more. You have bought this temple time it sorely needed, $N.' WHERE `ID` = 300942;
UPDATE `quest_template` SET `LogTitle` = 'High Priestess Arlokk', `LogDescription` = 'Defeat High Priestess Arlokk.', `QuestDescription` = 'The inner sanctum is sealed to us, guarded by one who should have been our sister in faith. High Priestess Arlokk keeps the way to Delrissa, and she will not yield to prayer or reason.$B$BI would spare her if I could. I cannot. Break through her guard, $N, and open the road to the heart of this corruption.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'High Priestess Arlokk is defeated.' WHERE `ID` = 300943;
UPDATE `quest_offer_reward` SET `RewardText` = 'Arlokk has fallen, and the way to the inner sanctum stands open at last. Steel yourself for what waits within, $N.' WHERE `ID` = 300943;
UPDATE `quest_template` SET `LogTitle` = 'The Defiled Highborne', `LogDescription` = 'Slay 8 Highborne Lichlings and 8 Highborne Summoners.', `QuestDescription` = 'The dead of old Zin-Azshari do not rest easy here. The Highborne who once worshipped beneath this roof have risen again, their spirits bound and befouled by dark magic. Highborne Lichlings drift the grounds, and Highborne Summoners call yet more from the earth.$B$BThere is no saving what they have become. Lay eight Lichlings and eight Summoners to rest, and let the temple grounds grow pure again.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'The corrupted Highborne are cleansed.' WHERE `ID` = 300944;
UPDATE `quest_offer_reward` SET `RewardText` = 'The defiled dead trouble these grounds no longer. With each one laid to rest, I feel the Moon''s light return a little to this place. Well done, $N.' WHERE `ID` = 300944;
UPDATE `quest_template` SET `LogTitle` = 'Moonkin Madness', `LogDescription` = 'Slay 10 Moonkin Oracles and 5 Moonkin Matriarchs.', `QuestDescription` = 'It grieves me most of all to ask this. The moonkin were Elune''s own children, gentle guardians of these groves. The corruption has driven them to raving madness, and the Moonkin Oracles and their Matriarchs now turn on all who near them.$B$BThere is no cure for what ails them, $N. Ten Oracles and five Matriarchs must be given the mercy of a clean death. Do this last kindness for them.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'The maddened moonkin are at peace.' WHERE `ID` = 300945;
UPDATE `quest_offer_reward` SET `RewardText` = 'They are at peace now, their madness ended. May Elune gather her children back into her light. You carry a heavy mercy, $N, and I will not forget it.' WHERE `ID` = 300945;
UPDATE `quest_template` SET `LogTitle` = 'Eldreth Incursion', `LogDescription` = 'Slay 8 Eldreth Sorcerers and 6 Eldreth Seethers.', `QuestDescription` = 'Where corruption festers, demons gather. The Eldreth have clawed their way into the temple, Eldreth Sorcerers weaving their foul spells and Eldreth Seethers burning with fel hunger. They mean to make this holy ground a doorway for worse things still.$B$BDrive them back into the shadow they crawled from, $N. Eight Sorcerers and six Seethers, and the temple will be secure once more.', `AreaDescription` = 'Temple of Elune', `QuestCompletionLog` = 'The Eldreth demons are driven back.' WHERE `ID` = 300946;
UPDATE `quest_offer_reward` SET `RewardText` = 'The Eldreth are banished and the temple stands secure. You have done Elune a great service this day, $N. Her light shines the brighter for it.' WHERE `ID` = 300946;
UPDATE `quest_template` SET `LogTitle` = 'Stirrings in the Drowned City', `LogDescription` = 'Speak with Magister Idona at the Ruins of Zin-Azshari.', `QuestDescription` = 'You have a stout heart, $N, and I have need of it. South of here lie the Ruins of Zin-Azshari, the drowned capital of Queen Azshara''s Highborne. The old stones are stirring, and dark magic gathers in them anew.$B$BMagister Idona has gone ahead to study the disturbance, and she works alone in a perilous place. Seek her out at the ruins. Whatever she has found, she should not face it without capable hands at her side.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found Magister Idona.' WHERE `ID` = 300950;
UPDATE `quest_template` SET `LogTitle` = 'Corruption in the Deep', `LogDescription` = 'Speak with Elder Brownpaw at Timbermaw Deep.', `QuestDescription` = 'Word has come up from the sacred caves, $N, and it is grim. A great corruption spreads through the tunnels the Timbermaw hold holy, and the furbolgs cannot stem it alone.$B$BElder Brownpaw has called for warriors brave enough to descend into that darkness. Go to him at Timbermaw Deep. The Timbermaw have ever been friends to those who walk the wilds honestly, and they will not forget aid freely given.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found Elder Brownpaw.' WHERE `ID` = 300951;
UPDATE `quest_template` SET `LogTitle` = 'The Dark Iron Invasion', `LogDescription` = 'Speak with Prospector Khazgorm near Spitelash Depths.', `QuestDescription` = 'The tides bring more than naga to these shores, $N. Deep beneath the crater the Dark Iron have come burrowing, and Prospector Khazgorm swears they dig for something better left buried.$B$BI command the waters, not the stone, and this hunt is not mine to lead. Khazgorm waits near the Spitelash Depths. Gather allies with iron in their spines and find him swiftly, before the mountain-folk pry loose whatever they seek.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found Prospector Khazgorm.' WHERE `ID` = 300952;
UPDATE `quest_template` SET `LogTitle` = 'The Fel Pit Beckons', `LogDescription` = 'Speak with Slayer Vorith at The Fel Pit.', `QuestDescription` = 'I feel it in my own blood, $N. The Fel Pit swells with demons, and the fel that stains me stirs whenever their number grows. I know that pull too well to ignore it.$B$BSlayer Vorith is marshalling an assault on the pit, and only the strongest have any business answering. Find Vorith and stand with him. Someone must burn this wound in the world shut before it swallows more souls than mine.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found Slayer Vorith.' WHERE `ID` = 300953;
UPDATE `quest_template` SET `LogTitle` = 'The Sanctum Guardian', `LogDescription` = 'Speak with the Image of Arcanigos at the Sanctum of the Highborne.', `QuestDescription` = 'I have fought this war longer than I care to count, $N, and I have learned to know a true champion from a fool with a sword. The Sanctum of the Highborne holds secrets that could shift the whole of this struggle, if a worthy hand can wrest them free.$B$BThe blue dragonflight guards those secrets jealously. They have set a guardian projection, an Image of Arcanigos, to weigh any who would enter. Present yourself to it at the Sanctum. This will test you as nothing yet has.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found the Image of Arcanigos.' WHERE `ID` = 300954;
UPDATE `quest_template` SET `LogTitle` = 'The Priestess of Elune', `LogDescription` = 'Speak with Priestess Lunara at the Temple of Elune.', `QuestDescription` = 'I keep watch over the drakes and the arcane surges, $N, and I have neither the faith nor the patience for holy matters. But the Temple of Elune festers with a corruption I cannot leave unanswered.$B$BPriestess Lunara holds what remains of that sanctuary, and she is calling for champions to cleanse it. Go to her at the Temple of Elune. Give her the strength she asks for, and do not let that place fall while I am occupied with my own charges.', `AreaDescription` = 'Azshara Crater', `QuestCompletionLog` = 'You have found Priestess Lunara.' WHERE `ID` = 300955;
UPDATE `quest_template` SET `LogTitle` = 'Scourge in the Sanctum', `LogDescription` = 'Defeat the Ymirjar Dusk Shaman.', `QuestDescription` = 'I am the Image of Arcanigos, sent by the blue flight to watch over what the Highborne left behind. Their arrogance tore the Well of Eternity asunder, and still their old sanctum bleeds power into the world. Now the Scourge have come to feast upon it.$B$BTheir host here answers to a Ymirjar Dusk Shaman, a wielder of death-magic who defiles these halls with every breath. Destroy the shaman, mortal, and prove you are worthy to tread deeper.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'The Ymirjar Dusk Shaman is destroyed.' WHERE `ID` = 300960;
UPDATE `quest_offer_reward` SET `RewardText` = 'The Dusk Shaman''s death-magic is stilled, and the Scourge falter at the threshold. You have taken the first step, mortal. Do not mistake it for the last.' WHERE `ID` = 300960;
UPDATE `quest_template` SET `LogTitle` = 'Magister Kalendris', `LogDescription` = 'Defeat Magister Kalendris.', `QuestDescription` = 'The Highborne spirits do not linger here by chance. One binds them still: Magister Kalendris, a soul as proud in undeath as he was in life. He clings to the arcane that damned his people, and through him it commands the restless dead of the Sanctum.$B$BSever that bond, mortal. Defeat Kalendris, and the spirits he yokes will begin to slip his grasp.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'Magister Kalendris is defeated.' WHERE `ID` = 300961;
UPDATE `quest_offer_reward` SET `RewardText` = 'Kalendris falls, and I feel his hold upon the spirits weaken. The old sins of the Highborne are not so easily buried, but you have loosened one thread of them today.' WHERE `ID` = 300961;
UPDATE `quest_template` SET `LogTitle` = 'The Forgotten Ones', `LogDescription` = 'Slay 10 Forgotten Ones.', `QuestDescription` = 'Beware the deep places of this Sanctum, mortal. Where arcane power pools untended, older and hungrier things take shape. The Forgotten Ones slither through the shadows here, echoes of a madness that has no name in your tongue.$B$BThey must not be left to grow. Cleanse ten of the Forgotten Ones from this sacred ground before their whispers take root.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'Ten Forgotten Ones are cleansed.' WHERE `ID` = 300962;
UPDATE `quest_offer_reward` SET `RewardText` = 'The Forgotten Ones are scattered back into the dark. Their kind can never be wholly destroyed, only held at bay. You have held them, and that is no small thing.' WHERE `ID` = 300962;
UPDATE `quest_template` SET `LogTitle` = 'Arcane Sentinels', `LogDescription` = 'Destroy 10 Arcane Sentinels.', `QuestDescription` = 'The Highborne built well, mortal, I will grant them that. The Arcane Sentinels they set to guard these halls still stand their watch, though the hands that made them are ten thousand years in dust. They know no ally now, and they will strike any who pass.$B$BI have no wish to see you unmade by the dead''s forgotten machines. Bring down ten of the Arcane Sentinels and clear the way ahead.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'Ten Arcane Sentinels are destroyed.' WHERE `ID` = 300963;
UPDATE `quest_offer_reward` SET `RewardText` = 'The Sentinels stand silent at last, their vigil ended. Even the finest works of the Highborne come to ruin. Let that be a lesson worth carrying, mortal.' WHERE `ID` = 300963;
UPDATE `quest_template` SET `LogTitle` = 'Scourge Infestation', `LogDescription` = 'Slay 12 Darkmender''s Ghouls and 8 Shadowy Necromancers.', `QuestDescription` = 'The Scourge do not relent, mortal. Where their shaman fell, more of the plague pours in behind. Darkmender''s Ghouls shamble through the outer halls, driven on by Shadowy Necromancers who raise them faster than they can be cut down.$B$BThis tide must be broken here, or it will drown the Sanctum entirely. Destroy twelve of Darkmender''s Ghouls and eight of the Shadowy Necromancers who command them.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'The Scourge infestation is purged.' WHERE `ID` = 300964;
UPDATE `quest_offer_reward` SET `RewardText` = 'The ghouls fall still and the necromancers with them. The Scourge tide is broken for now, mortal. Rest but a moment; this war is far from won.' WHERE `ID` = 300964;
UPDATE `quest_template` SET `LogTitle` = 'Highborne Spirits', `LogDescription` = 'Slay 10 Servants of Setaal and 8 Moonrest Highborne.', `QuestDescription` = 'Listen, mortal. The wailing you hear is grief ten thousand years old. The Servants of Setaal and the Moonrest Highborne are bound spirits, chained to this place by the pride that drowned their city. They cannot rest while that binding holds.$B$BIt is a mercy, not a slaughter, that I ask of you. Release ten Servants of Setaal and eight of the Moonrest Highborne, and let these ancient sinners find the peace they were so long denied.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'The bound Highborne spirits are released.' WHERE `ID` = 300965;
UPDATE `quest_offer_reward` SET `RewardText` = 'The spirits fade, and the wailing softens toward silence. Even the Highborne''s oldest sins may find absolution in the end. You have given it to them, mortal. The blue flight marks your name.' WHERE `ID` = 300965;
UPDATE `quest_template` SET `LogTitle` = 'Lady Nightswood', `LogDescription` = 'Slay Lady Nightswood.', `QuestDescription` = 'One horror yet holds the upper tier, mortal. The banshee Lady Nightswood shrieks her torment across the Sanctum, and her voice alone can shatter the mind of the unready. She is the last barrier between us and the peace this place has earned.$B$BAscend, and silence her scream forever. Do this, and the Sanctum of the Highborne will know quiet for the first time in an age.', `AreaDescription` = 'Sanctum of the Highborne', `QuestCompletionLog` = 'Lady Nightswood is silenced.' WHERE `ID` = 300966;
UPDATE `quest_offer_reward` SET `RewardText` = 'The banshee''s scream is silenced at last, and a stillness settles over the Sanctum. You have done what the blue flight could not send its own to do. Go now, mortal, and carry the weight of what you have seen. Azshara''s ruin still whispers to any who would listen.' WHERE `ID` = 300966;
UPDATE `quest_template` SET `LogTitle` = 'Welcome to Azshara Crater', `LogDescription` = 'Speak with Hervikus the Chaotic at the crater''s rim.', `QuestDescription` = 'Well met, $N. I am Hervikus -- some name me the Chaotic, and standing at the lip of this place, you will soon understand why.$B$BAzshara Crater was gouged into the old Highborne lands when the Well of Eternity shattered the world. The wound never closed. Arcane fire still churns in its depths, and it draws the lost and the wicked from every corner of Azeroth -- ghosts of Queen Azshara''s court, naga returned to their drowned halls, fel-maddened satyrs, and darker things still.$B$BFew have walked the crater floor and climbed back out. Keep your blade close and your wits closer, $N, and this place may yet forge a champion of you. Welcome to Azshara Crater.', `AreaDescription` = 'The rim of Azshara Crater.', `QuestCompletionLog` = 'May the crater temper you, $N, and not devour you.' WHERE `ID` = 820056;
UPDATE `quest_template` SET `LogTitle` = 'Welcome to Dark Chaos', `LogDescription` = 'Report to Warden Stonebrook near the outpost camp.', `QuestDescription` = 'Before you set foot on the crater floor, there is one you must meet, $N.$B$BWarden Stonebrook holds the outpost at the crater''s edge, and he takes the measure of every champion who wanders in. He will see you armed, provisioned, and pointed toward the first of the crater''s many trials.$B$BYou will find him just past the camp''s edge, watching the beasts that prowl below with a hunter''s patience. Report to him, and your journey truly begins.', `AreaDescription` = 'Just beyond the outpost camp.', `QuestCompletionLog` = 'Report to Warden Stonebrook.' WHERE `ID` = 820057;
UPDATE `quest_offer_reward` SET `RewardText` = 'So Hervikus sent you down the slope, did he? Aye -- you''ve the look of one who might last a while. Let''s put you to work, $N.' WHERE `ID` = 820057;
